#!/usr/bin/env python3
# Uso: python3 -I -B ct_pruebas_validador_listas.py <salida.json>   (sin base de datos; valores FICTICIOS sólo para probar el validador, jamás se copian a la guarda)
import json, os, re, subprocess, sys, tempfile
HERE = os.path.dirname(os.path.abspath(__file__)); V = os.path.join(HERE, "ct_validar_listas_destinos.py"); G = os.path.join(HERE, "cci_dev_NO_EJECUTADOS", "00_guarda_destino.sql"); REC = []; T = tempfile.mkdtemp(prefix="lst.")
def v(modo, ruta, *x): r = subprocess.run(["python3", "-I", "-B", V, modo, ruta, *x], capture_output=True, text=True); return r.returncode, (r.stdout + r.stderr).strip()
def lista(nombre, txt): p = os.path.join(T, nombre); open(p, "w").write(txt if isinstance(txt, str) else json.dumps(txt)); return p
def caso(i, ob, esp, res):
    rc, o = res; c = re.findall(r"\[(L-[A-Z-]+)\]", o); ok = (rc == 0 and o.startswith("OK")) if esp == "OK" else (rc == 3 and c[:1] == [esp])
    REC.append({"id": i, "objetivo": ob, "esperado": esp, "observado": "rc=%d %s" % (rc, o[:90]), "estado": "PASS" if ok else "FAIL"}); print("PASS" if ok else "FAIL", i, ob, "->", o[:70])
S = lambda d, p: {"schema": "cci-listas-destinos/1", "dev_allow": d, "prod_deny": p}; RQ = "--requerir-no-vacias"
caso("EXT03-01", "listas válidas (valores ficticios de prueba)", "OK", v("archivo", lista("a", S(["7710738743337034195|cci_dev"], ["7710738747164414455"])), RQ))
caso("EXT03-02", "ambas listas vacías cuando se exige no vacías", "L-DEV-VACIA", v("archivo", lista("b", S([], [])), RQ))
caso("EXT03-03", "prod_deny vacía cuando se exige", "L-PROD-VACIA", v("archivo", lista("c", S(["7710738743337034195|cci_dev"], [])), RQ))
caso("EXT03-04", "dev_allow vacía con prod_deny llena", "L-DEV-VACIA", v("archivo", lista("d", S([], ["7710738747164414455"])), RQ))
caso("EXT03-05", "listas vacías sin exigir no-vacías: formato válido (informativo)", "OK", v("archivo", lista("e", S([], []))))
caso("EXT03-06", "dev_allow sin separador '|'", "L-DEV-FORMATO", v("archivo", lista("f", S(["7710738743337034195"], ["7710738747164414455"])), RQ))
caso("EXT03-07", "dev_allow con dos '|'", "L-DEV-FORMATO", v("archivo", lista("g", S(["1|a|b"], ["67890"])), RQ))
caso("EXT03-08", "system_identifier no numérico", "L-DEV-SYSID", v("archivo", lista("h", S(["abc|cci_dev"], ["67890"])), RQ))
caso("EXT03-09", "system_identifier con ceros a la izquierda", "L-DEV-SYSID", v("archivo", lista("i", S(["0123|cci_dev"], ["67890"])), RQ))
caso("EXT03-10", "system_identifier fuera de uint64", "L-DEV-SYSID", v("archivo", lista("j", S(["18446744073709551616|cci_dev"], ["67890"])), RQ))
caso("EXT03-11", "identificador de relleno (todos los dígitos iguales)", "L-DEV-SYSID-MARCADOR", v("archivo", lista("k", S(["1111111111|cci_dev"], ["67890"])), RQ))
caso("EXT03-12", "base con inyección SQL (comilla)", "L-DEV-BASE", v("archivo", lista("l", S(["12345|x'); drop table t;--"], ["67890"])), RQ))
caso("EXT03-13", "base vacía", "L-DEV-BASE", v("archivo", lista("m", S(["12345|"], ["67890"])), RQ))
caso("EXT03-14", "base marcador 'TBD'", "L-DEV-BASE-MARCADOR", v("archivo", lista("n", S(["12345|TBD"], ["67890"])), RQ))
caso("EXT03-15", "entrada duplicada en dev_allow", "L-DEV-DUPLICADA", v("archivo", lista("o", S(["12345|a", "12345|a"], ["67890"])), RQ))
caso("EXT03-16", "entrada duplicada en prod_deny", "L-PROD-DUPLICADA", v("archivo", lista("p", S(["12345|a"], ["67890", "67890"])), RQ))
caso("EXT03-17", "mismo clúster en DEV y en prod_deny (solapamiento)", "L-SOLAPAMIENTO", v("archivo", lista("q", S(["12345|a"], ["12345"])), RQ))
caso("EXT03-18", "prod_deny con formato 'id|base'", "L-PROD-FORMATO", v("archivo", lista("r", S(["12345|a"], ["67890|b"])), RQ))
caso("EXT03-19", "entrada que no es cadena (número)", "L-DEV-FORMATO", v("archivo", lista("s", S([12345], ["67890"])), RQ))
caso("EXT03-20", "claves extra en el archivo", "L-ESQUEMA", v("archivo", lista("t", {"schema": "cci-listas-destinos/1", "dev_allow": ["1|a"], "prod_deny": ["67890"], "extra": 1}), RQ))
caso("EXT03-21", "schema incorrecto", "L-ESQUEMA", v("archivo", lista("u", {"schema": "otro", "dev_allow": ["1|a"], "prod_deny": ["67890"]}), RQ))
caso("EXT03-22", "JSON con clave duplicada", "L-CLAVE-DUPLICADA", v("archivo", lista("w", '{"schema":"cci-listas-destinos/1","dev_allow":["1|a"],"dev_allow":["1|a"],"prod_deny":["67890"]}'), RQ))
caso("EXT03-23", "JSON inválido", "L-JSON", v("archivo", lista("x", "{no es json"), RQ))
caso("EXT03-24", "archivo ausente", "L-ARCHIVO-AUSENTE", v("archivo", os.path.join(T, "no_existe.json"), RQ))
caso("EXT03-25", "listas no son arreglos", "L-TIPO", v("archivo", lista("y", {"schema": "cci-listas-destinos/1", "dev_allow": "1|a", "prod_deny": "2"}), RQ))
caso("EXT03-26", "demasiadas entradas (65)", "L-DEMASIADAS", v("archivo", lista("z", S(["%d|a" % (i + 1) for i in range(65)], ["99999999"])), RQ))
caso("EXT03-27", "guarda REAL actual (listas vacías) con exigencia de no vacías: debe RECHAZAR (EXT-03 sigue bloqueado)", "L-DEV-VACIA", v("guarda", G, RQ))
caso("EXT03-28", "guarda real: estructura reconocida (vacía sin exigencia)", "OK", v("guarda", G))
g = open(G, encoding="utf-8").read(); caso("EXT03-29", "guarda con la línea de allowlist eliminada", "L-GUARDA-ESTRUCTURA", v("guarda", lista("g1.sql", g.replace("-- @@DEV_ALLOW@@", "-- x"))))
caso("EXT03-30", "guarda con literal no estático (concatenación)", "L-GUARDA-LITERAL", v("guarda", lista("g2.sql", g.replace("array[]::text[];  -- @@DEV_ALLOW@@", "array['1|a'||'b']::text[];  -- @@DEV_ALLOW@@"))))
caso("EXT03-31", "guarda con listas válidas inyectadas (control positivo)", "OK", v("guarda", lista("g3.sql", g.replace("array[]::text[];  -- @@DEV_ALLOW@@", "array['12345|cci_dev']::text[];  -- @@DEV_ALLOW@@").replace("array[]::text[];  -- @@PROD_DENY@@", "array['67890']::text[];  -- @@PROD_DENY@@")), RQ))
caso("EXT03-32", "guarda con solapamiento inyectado", "L-SOLAPAMIENTO", v("guarda", lista("g4.sql", g.replace("array[]::text[];  -- @@DEV_ALLOW@@", "array['12345|cci_dev']::text[];  -- @@DEV_ALLOW@@").replace("array[]::text[];  -- @@PROD_DENY@@", "array['12345']::text[];  -- @@PROD_DENY@@")), RQ))
rc, o = v("generar", lista("ok.json", S(["12345|cci_dev"], ["67890"]))); REC.append({"id": "EXT03-33", "objetivo": "generar: imprime las dos líneas literales exactas", "esperado": "dos líneas con marcadores @@", "observado": o[:120], "estado": "PASS" if rc == 0 and o.count("@@") == 4 else "FAIL"}); print(REC[-1]["estado"], "EXT03-33")
rc, o = v("generar", lista("vac.json", S([], []))); REC.append({"id": "EXT03-34", "objetivo": "generar con listas vacías: rechaza (no produce líneas)", "esperado": "L-DEV-VACIA", "observado": o[:80], "estado": "PASS" if rc == 3 and "L-DEV-VACIA" in o else "FAIL"}); print(REC[-1]["estado"], "EXT03-34")
json.dump(REC, open(sys.argv[1], "w", encoding="utf-8"), ensure_ascii=False, indent=1); n = sum(r["estado"] == "FAIL" for r in REC); print("TOTAL=%d PASS=%d FAIL=%d" % (len(REC), len(REC) - n, n)); sys.exit(1 if n else 0)
